<style>
:root{--n88-red:#e4002b;--n88-ink:#292929;--n88-muted:#858585;--n88-bg:#f1f2f3;--n88-line:#e4e4e4;--n88-shadow:0 10px 28px rgba(25,31,40,.08)}*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:var(--n88-bg);color:var(--n88-ink);font-family:"Be Vietnam Pro",Arial,sans-serif}body,html{max-width:100%;overflow-x:hidden}a{color:inherit;text-decoration:none}img{display:block;max-width:100%}.n88-container{width:min(1360px,calc(100% - 48px));margin:auto}.n88-header{position:relative;z-index:50;background:#fff;border-top:2px solid var(--n88-red);box-shadow:0 2px 12px rgba(0,0,0,.05)}.n88-nav-wrap{width:min(1540px,calc(100% - 32px));min-height:86px;margin:auto;display:flex;align-items:center;gap:24px}.n88-brand{display:none;flex:0 0 auto}.n88-brand img{width:150px;max-height:58px;object-fit:contain}.n88-brand strong{color:var(--n88-red);font-size:25px;font-weight:800}.n88-nav{display:flex;align-items:center;gap:34px;flex:1;min-width:0}.n88-nav a{position:relative;padding:31px 0;color:#333;font-size:16px;font-weight:700;white-space:nowrap}.n88-nav a::after{content:"";position:absolute;left:0;right:100%;bottom:21px;height:3px;background:var(--n88-red);transition:.25s}.n88-nav a:hover,.n88-nav a.is-active{color:var(--n88-red)}.n88-nav a:hover::after,.n88-nav a.is-active::after{right:0}.n88-header-tools{display:flex;align-items:center;gap:15px}.n88-header-tools button,.n88-social a{width:34px;height:34px;border:0;background:transparent;display:grid;place-items:center;font-size:17px;cursor:pointer}.n88-social{display:flex}.n88-menu-button{display:none;border:0;background:none;font-size:23px}.n88-search{position:absolute;right:max(16px,calc((100% - 1540px)/2));top:70px;width:290px;padding:10px;display:flex;opacity:0;visibility:hidden;transform:translateY(-8px);background:#fff;box-shadow:var(--n88-shadow);transition:.2s}.n88-search.is-open{opacity:1;visibility:visible;transform:none}.n88-search input{width:100%;border:1px solid var(--n88-line);padding:12px}.n88-search button{width:48px;border:0;background:var(--n88-red);color:#fff}.n88-main{padding:54px 0 85px}.n88-hotbar{display:grid;grid-template-columns:150px 1fr 1fr;align-items:center;margin-bottom:32px;background:#fff;min-height:64px}.n88-hotbar strong{height:100%;display:flex;align-items:center;gap:11px;padding:0 20px;background:var(--n88-red);color:#fff;text-transform:uppercase;letter-spacing:.05em}.n88-hotbar a{display:flex;align-items:center;gap:16px;padding:11px 22px;font-weight:600;border-right:1px solid var(--n88-line)}.n88-hotbar a span{width:40px;height:40px;border-radius:50%;display:grid;place-items:center;background:#edf0f4;color:var(--n88-red);font-weight:800}.n88-hero{position:relative;display:grid;grid-template-columns:2fr 1fr 1fr;grid-template-rows:350px 350px;gap:2px;margin-bottom:66px;background:#fff}.n88-hero-card{position:relative;overflow:hidden}.n88-hero-card--0{grid-row:1/3}.n88-hero-card a,.n88-hero-card img,.n88-shade{position:absolute;inset:0;width:100%;height:100%}.n88-hero-card img{object-fit:cover;transition:transform .7s}.n88-hero-card:hover img{transform:scale(1.04)}.n88-shade{background:linear-gradient(180deg,rgba(0,0,0,.05) 25%,rgba(0,0,0,.8) 100%)}.n88-hero-card div{position:absolute;z-index:2;left:28px;right:28px;bottom:28px;color:#fff}.n88-hero-card--0 div{left:44px;right:44px;bottom:42px}.n88-hero-card h1,.n88-hero-card h2{margin:0 0 14px;font-size:22px;line-height:1.38}.n88-hero-card h1{font-size:32px}.n88-hero-card p{max-width:740px;margin:0 0 20px;line-height:1.6}.n88-hero-card small,.n88-panel small{color:#929292}.n88-hero-card small{color:#fff}.n88-hero-card small b,.n88-panel small b{margin-left:25px;font-weight:500}.n88-latest-row{position:relative;display:grid;grid-template-columns:minmax(0,2.7fr) minmax(310px,1fr);gap:32px;margin-bottom:42px}.n88-panel{position:relative;background:#fff;box-shadow:var(--n88-shadow)}.n88-panel>header{min-height:60px;padding:0 24px;display:flex;align-items:center;border-top:3px solid var(