--n88-red);color:#fff}.n88-footer-grid{display:grid;grid-template-columns:1.15fr 1.15fr 1.1fr 1.1fr;gap:52px;padding:64px 0}.n88-footer-logo img{width:180px;max-height:70px;object-fit:contain;object-position:left}.n88-footer-logo strong{font-size:34px;font-weight:800}.n88-footer-about p{margin-top:28px;line-height:1.75}.n88-footer h2{margin:0 0 27px;font-size:21px}.n88-footer h2::after{content:"";display:block;width:42px;height:3px;margin-top:14px;background:#fff}.n88-footer-posts{display:grid;gap:18px}.n88-footer-posts a{line-height:1.5;font-weight:600}.n88-tags{display:flex;flex-wrap:wrap;gap:9px}.n88-tags a{padding:8px 16px;border-radius:20px;background:#fff;color:#666}.n88-map iframe,.n88-map>div{width:100%;height:275px;border:0;background:#fff}.n88-map>div{display:grid;place-items:center;color:var(--n88-red)}.n88-footer-social{display:flex;gap:18px;margin-top:28px}.n88-footer-bottom{padding:24px 0;background:rgba(0,0,0,.08)}[data-n88-reveal]{opacity:0;transform:translateY(20px);transition:.6s}[data-n88-reveal].is-visible{opacity:1;transform:none}.n88-inner{padding:70px 0 90px}.n88-inner-head{margin-bottom:28px;padding:34px;background:#fff;border-top:3px solid var(--n88-red)}.n88-inner-head h1{margin:0;font-size:34px}.n88-list{display:grid;grid-template-columns:repeat(3,1fr);gap:28px}.n88-list article{background:#fff;box-shadow:var(--n88-shadow)}.n88-list img{width:100%;height:240px;object-fit:cover}.n88-list article div{padding:22px}.n88-list h2{font-size:19px;line-height:1.5}.n88-list p{color:#666;line-height:1.65}.n88-article{max-width:940px;margin:auto;padding:70px 24px 90px}.n88-article>article{padding:48px;background:#fff;box-shadow:var(--n88-shadow)}.n88-article h1{font-size:40px;line-height:1.3}.n88-article-cover{width:100%;max-height:520px;object-fit:cover;margin:30px 0}.n88-article-body{font-size:17px;line-height:1.85}.n88-article-body img{max-width:100%;height:auto}.n88-contact-card{max-width:850px;padding:40px;background:#fff;box-shadow:var(--n88-sha