@media(max-width:900px){.n88-nav-wrap{min-height:72px}.n88-menu-button{display:block;margin-left:auto}.n88-nav{position:absolute;left:0;right:0;top:72px;display:none;padding:18px 24px;background:#fff;box-shadow:var(--n88-shadow);flex-direction:column;align-items:flex-start}.n88-nav.is-open{display:flex}.n88-nav a{width:100%;padding:9px 0}.n88-nav a::after{display:none}.n88-hotbar{grid-template-columns:130px 1fr}.n88-hotbar a:last-child{display:none}.n88-hero{grid-template-columns:1fr 1fr;grid-template-rows:460px repeat(2,250px)}.n88-hero-card--0{grid-column:1/3;grid-row:auto}.n88-latest-row{grid-template-columns:1fr}.n88-health-grid{grid-template-columns:repeat(2,1fr)}.n88-columns{grid-template-columns:1fr}.n88-footer-grid{grid-template-columns:1fr 1fr}.n88-list{grid-template-columns:1fr 1fr}}
