.n88-topbar{border-bottom:1px solid var(--n88-line);background:#f7f7f8}.n88-topbar-inner{min-height:42px;display:flex;align-items:center;justify-content:flex-end}.n88-topbar .n88-header-tools{gap:9px}.n88-topbar .sf-language-switcher{position:static;z-index:70}.n88-topbar .sf-language-switcher summary{min-height:32px;padding:5px 9px;background:#fff;box-shadow:none}.n88-nav-wrap.n88-container{width:min(1360px,calc(100% - 48px));min-height:74px}.n88-nav-wrap .n88-nav{justify-content:center}.n88-nav-wrap .n88-nav a{padding-block:25px}.n88-nav-wrap .n88-nav a::after{bottom:15px}.n88-search{right:max(24px,calc((100% - 1360px)/2));top:112px}.n88-hero-card:not(.n88-hero-card--0) h2{font-size:18px;line-height:1.35}.n88-latest-panel,.n88-video-panel{height:100%}.n88-latest-grid article{display:flex;min-width:0;flex-direction:column}.n88-latest-grid h3{display:-webkit-box;min-height:51px;margin-bottom:10px;overflow:hidden;-webkit-box-orient:vertical;-webkit-line-clamp:2}.n88-latest-grid p{display:-webkit-box;overflow:hidden;-webkit-box-orient:vertical;-webkit-line-clamp:2}.n88-video-grid{grid-template-columns:1fr}.n88-video-grid article{display:grid;grid-template-columns:150px minmax(0,1fr);gap:0 16px;align-content:start}.n88-video-grid article>a{display:contents}.n88-video-grid article>a>span{grid-row:1/3}.n88-video-grid img{height:130px}.n88-video-grid h3{grid-column:2;margin:0}.n88-video-grid p{grid-column:2;display:-webkit-box;margin-top:8px;overflow:hidden;-webkit-box-orient:vertical;-webkit-line-clamp:3}
