.n88-footer{position:relative;isolation:isolate;overflow:hidden;background:radial-gradient(circle at 12% 18%,rgba(32,205,255,.16),transparent 30%),radial-gradient(circle at 88% 74%,rgba(228,0,43,.14),transparent 32%),linear-gradient(145deg,#081522 0%,#0a1a2b 52%,#050b13 100%);color:#eaf6ff;border-top:1px solid rgba(71,213,255,.38);box-shadow:inset 0 1px 0 rgba(255,255,255,.04)}
